function newsRow(kind){var link=function(h,x){return'<span class="it"><a href="'+h+'">'+x+'</a></span>';};var sw=[['all',t('all')],['patch',t('newsPatch')],['notice',t('newsNotice')]].map(function(c){return'<button type="button" class="nw-btn" data-nk="'+c[0]+'" aria-pressed="'+(kind===c[0])+'">'+c[1]+'</button>';}).join('');var items=newsItems(4,kind).map(function(x){var p=x.p,first=p.b.filter(function(b){return b[0]!=='h';})[0],txt=first?patchText(first):'';return link('#/'+x.k+'?d='+p.d,'<span class="nw-tag nw-'+x.k+'">'+t(x.k==='notice'?'newsNotice':'newsPatch')+'</span>'+p.d.slice(5).replace('-','.')+' <span lang="ko">'+esc(txt.length>26?txt.slice(0,26)+'…':txt)+'</span>');});if(!items.length)items=['<span class="it off">'+t('noticeNone')+'</span>'];var more=[];if(kind!=='notice')more.push(link('#/patch',t('patchAll',{n:PATCHES.length})));if(kind!=='patch'&&NOTICES.length)more.push(link('#/notice',t('noticeAll',{n:NOTICES.length})));return'<span class="lb">News<span class="nw-sw" role="group" aria-label="'+esc(t('category'))+'">'+sw+'</span></span>'+items.concat(more).join('');}
var WEEK=['일','월','화','수','목','금','토'];function patchText(b){return b[0]==='tbl'?b[1].map(function(r){return r.join(' ');}).join(' '):b[1];}
function patchHay(p){return p.d+' '+p.b.map(patchText).join(' ');}
