function renderPatch(params,kind){kind=kind||'patch';var DATA=FEEDS[kind].data,CATS=FEEDS[kind].cats;if(!DATA.length){app.innerHTML=head(t(kind+'Title'),null,t('noticeNone'));return;}
var q=params.q||'',cat='all',month=params.d?params.d.slice(0,7):'all',limit=25,focus=params.d||null;var months=[];DATA.forEach(function(p){var m=p.d.slice(0,7);if(months.indexOf(m)<0)months.push(m);});months.reverse();app.innerHTML=head(t(kind+'Title'),t('countN',{n:DATA.length}),t(kind+'Desc',{a:DATA[0].d,b:DATA[DATA.length-1].d}))+
(LANG!=='ko'?'<p class="note-banner">'+esc(t(kind+'KoOnly'))+'</p>':'')+'<div class="ttabs" role="tablist" aria-label="'+esc(t('patchMonth'))+'" id="ptabs"></div>'+'<div class="frow"><label for="pq" class="sr-only">'+t('filter')+'</label><input class="fin q" id="pq" type="search" autocomplete="off" placeholder="'+esc(t(kind+'FilterPh'))+'"></div>'+'<div class="tags" role="group" aria-label="'+esc(t('category'))+'" id="pcats"></div>'+'<p class="faint" style="margin:8px 0 0;font-size:12.5px" id="pcount" aria-live="polite"></p>'+'<div id="pbody" class="ptl"></div>';var qi=document.getElementById('pq');qi.value=q;qi.addEventListener('input',function(){q=qi.value;limit=25;focus=null;sync();draw();});function sync(){var ps=[];if(month!=='all')ps.push('m='+month);if(q)ps.push('q='+encodeURIComponent(q));history.replaceState(null,'','#/'+kind+(ps.length?'?'+ps.join('&'):''));}
if(params.m&&months.indexOf(params.m)>=0)month=params.m;function draw(){var terms=splitTerms(q);var base=DATA.filter(function(p){return!terms.length||matchAll(patchHay(p),terms);});var inMonth=base.filter(function(p){return month==='all'||p.d.slice(0,7)===month;});document.getElementById('ptabs').innerHTML=[['all',t('all')]].concat(months.map(function(m){return[m,m.replace('-','.')];})).map(function(m){var n=m[0]==='all'?base.length:base.filter(function(p){return p.d.slice(0,7)===m[0];}).length;return'<button class="ttab" type="button" role="tab" data-m="'+m[0]+'" aria-selected="'+(month===m[0])+'">'+m[1]+' <span class="c">/'+n+'</span></button>';}).join('');document.querySelectorAll('#ptabs button').forEach(function(b){b.addEventListener('click',function(){month=b.getAttribute('data-m');limit=25;focus=null;sync();draw();});});document.getElementById('pcats').innerHTML=[['all','']].concat(CATS).map(function(c){var n=c[0]==='all'?inMonth.length:inMonth.filter(function(p){return p.c.indexOf(c[0])>=0;}).length;return'<button class="tagb" type="button" data-c="'+c[0]+'" aria-pressed="'+(cat===c[0])+'">'+(c[1]?c[1]+' ':'')+t('pc_'+c[0])+'<span class="c">'+n+'</span></button>';}).join('');document.querySelectorAll('#pcats button').forEach(function(b){b.addEventListener('click',function(){cat=b.getAttribute('data-c');limit=25;draw();});});var list=inMonth.filter(function(p){return cat==='all'||p.c.indexOf(cat)>=0;}).slice().reverse();var days=[];list.forEach(function(p){var g=days[days.length-1];if(g&&g.d===p.d)g.items.push(p);else days.push({d:p.d,items:[p]});});document.getElementById('pcount').textContent=t('patchCount',{n:list.length,k:days.length});var el=document.getElementById('pbody');if(!days.length){el.innerHTML='<div class="empty">'+t(kind+'Empty')+'</div>';return;}
var shown=days.slice(0,limit);el.innerHTML=shown.map(function(g){var dt=new Date(g.d+'T00:00:00');return'<section class="pday'+(focus===g.d?' focus':'')+'" id="pd-'+g.d+'"><h3><span class="pd-date">'+g.d.replace(/-/g,'.')+'</span> <span class="pd-wd">('+(LANG==='ko'?WEEK[dt.getDay()]:dt.toLocaleDateString(LANG,{weekday:'short'}))+')</span></h3>'+
g.items.map(function(p){return'<article class="pcard" lang="ko"><div class="pc-meta">'+(p.t?'<span class="mono">'+p.t+'</span>':'')+p.c.map(function(c){return'<span class="pc-tag pc-'+c+'">'+t('pc_'+c)+'</span>';}).join('')+'</div><div class="pc-body">'+patchBlocks(p,terms)+'</div></article>';}).join('')+'</section>';}).join('')+(days.length>limit?'<div style="text-align:center;margin:16px 0"><button class="btn blue" type="button" id="pmore">'+t('showMore',{n:Math.min(25,days.length-limit),r:days.length-limit})+'</button></div>':'');var more=document.getElementById('pmore');if(more)more.addEventListener('click',function(){limit+=25;draw();});if(focus){var f=document.getElementById('pd-'+focus);if(f&&f.scrollIntoView)f.scrollIntoView({block:'start'});}}
draw();}
